const stats = {
  mean(values) {
    const nums = toNumbers('mean', values);
    return nums.reduce((a, b) => a + b, 0) / nums.length;
  },

  median(values) {
    const nums = toNumbers('median', values);
    const sorted = [...nums].sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    if (sorted.length % 2 === 1) {
      return sorted[mid];
    }
    return (sorted[mid - 1] + sorted[mid]) / 2;
  },

  variance(values) {
    const nums = toNumbers('variance', values);
    const m = stats.mean(nums);
    return nums.reduce((acc, v) => acc + (v - m) ** 2, 0) / nums.length;
