const assert = require('node:assert/strict');
const stats = require('../src/stats');

describe('stats', () => {
  describe('mean', () => {
    it('averages a plain list', () => {
      assert.equal(stats.mean([1, 2, 3, 4]), 2.5);
    });

    it('returns the value itself for a single element', () => {
      assert.equal(stats.mean([7]), 7);
    });

    it('throws on empty input', () => {
      assert.throws(() => stats.mean([]), TypeError);
    });
  });

  describe('median', () => {
    it('picks middle of odd-length list', () => {
      assert.equal(stats.median([3, 1, 2]), 2);
    });

    it('averages the two middles of even-length list', () => {
      assert.equal(stats.median([4, 1, 3, 2]), 2.5);
    });

    it('does not mutate the input array', () => {
      const input = [3, 1, 2];
      stats.median(input);
      assert.deepEqual(input, [3, 1, 2]);
    });
  });

  describe('variance / stddev', () => {
    it('computes population variance', () => {
      assert.equal(stats.variance([2, 4, 4, 4, 5, 5, 7, 9]), 4);
    });

    it('stddev of constant list is zero', () => {
      assert.equal(stats.stddev([5, 5, 5]), 0);
    });

    it('stddev is sqrt of variance', () => {
      assert.equal(stats.stddev([1, 2, 3, 4]), Math.sqrt(1.25));
    });
  });

  describe('min / max', () => {
    it('finds min and max', () => {
      assert.equal(stats.min([3, -1, 7]), -1);
      assert.equal(stats.max([3, -1, 7]), 7);
    });
  });

  describe('input validation', () => {
    it('rejects non-array input', () => {
      assert.throws(() => stats.mean('123'), TypeError);
    });

    it('rejects arrays containing non-numbers', () => {
      assert.throws(() => stats.median([1, '2', 3]), TypeError);
    });
  });
});

