'use strict';

const assert = require('node:assert/strict');

// 字符串工具：demo 项目的第三个示例模块
const strings = {
  capitalize(text) {
    requireString('capitalize', text);
    if (text.length === 0) {
      return text;
    }
    return text[0].toUpperCase() + text.slice(1);
  },

  camelCase(text) {
    requireString('camelCase', text);
    const parts = text
      .replace(/[-_.\s]+(.)?/g, (_, c) => (c ? c.toUpperCase() : ''))
      .split(/(?=[A-Z])/);
    if (parts.length === 0) {
      return '';
    }
    const [first, ...rest] = parts.join('').split('');
    if (rest.length === 0 && /[A-Z]/.test(first || '')) {
      return first.toLowerCase();
    }
    return text
      .replace(/[-_.\s]+(.)?/g, (_, c) => (c ? c.toUpperCase() : ''))
      .replace(/^./, (c) => c.toLowerCase());
  },

  truncate(text, maxLength) {
    requireString('truncate', text);
    if (!Number.isInteger(maxLength) || maxLength < 1) {
      throw new RangeError('truncate: maxLength must be an integer >= 1');
    }
    if (text.length <= maxLength) {
      return text;
    }
    if (maxLength <= 1) {
      return '…';
    }
    return `${text.slice(0, maxLength - 1)}…`;
  },

  reverseWords(text) {
    requireString('reverseWords', text);
    return text.split(/\s+/).filter(Boolean).reverse().join(' ');
  },

  countVowels(text) {
    requireString('countVowels', text);
    return (text.match(/[aeiouAEIOU]/g) || []).length;
  },

  isPalindrome(text) {
    requireString('isPalindrome', text);
    const normalized = text.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (normalized.length === 0) {
      return true;
    }
    return normalized === [...normalized].reverse().join('');
  },
};

function requireString(op, value) {
  if (typeof value !== 'string') {
    throw new TypeError(`${op}: expected string, got ${String(value)}`);
  }
}

module.exports = strings;

