'use strict';

const assert = require('node:assert/strict');
const strings = require('../src/strings');
const demo = require('../src/index');

describe('strings', () => {
  describe('capitalize', () => {
    it('uppercases the first letter only', () => {
      assert.equal(strings.capitalize('hello world'), 'Hello world');
    });

    it('leaves an empty string empty', () => {
      assert.equal(strings.capitalize(''), '');
    });
  });

  describe('camelCase', () => {
    it('converts kebab-case', () => {
      assert.equal(strings.camelCase('foo-bar-baz'), 'fooBarBaz');
    });

    it('converts snake_case and spaces', () => {
      assert.equal(strings.camelCase('hello world_test'), 'helloWorldTest');
    });

    it('lowercases a leading capital', () => {
      assert.equal(strings.camelCase('Foo Bar'), 'fooBar');
    });
  });

  describe('truncate', () => {
    it('keeps short text unchanged', () => {
      assert.equal(strings.truncate('short', 10), 'short');
    });

    it('appends ellipsis within the limit', () => {
      assert.equal(strings.truncate('a long sentence', 8), 'a long s…');
    });

    it('rejects non-positive maxLength', () => {
      assert.throws(() => strings.truncate('abc', 0), RangeError);
    });
  });

  describe('reverseWords', () => {
    it('reverses word order', () => {
      assert.equal(strings.reverseWords('the quick brown fox'), 'fox brown quick the');
    });

    it('collapses repeated whitespace', () => {
      assert.equal(strings.reverseWords('  a   b  '), 'b a');
    });
  });

  describe('countVowels', () => {
    it('counts vowels case-insensitively', () => {
      assert.equal(strings.countVowels('The Quick Brown Fox'), 5);
    });

    it('returns 0 when no vowels', () => {
      assert.equal(strings.countVowels('xyz'), 0);
    });
  });

  describe('isPalindrome', () => {
    it('detects a simple palindrome ignoring case and punctuation', () => {
      assert.equal(strings.isPalindrome('A man, a plan, a canal: Panama'), true);
    });

    it('rejects a non-palindrome', () => {
      assert.equal(strings.isPalindrome('hello'), false);
    });
  });

  describe('input validation', () => {
    it('rejects non-string input', () => {
      assert.throws(() => strings.capitalize(42), TypeError);
    });
  });
});

describe('package entry (src/index.js)', () => {
  it('exposes calculator', () => {
    assert.equal(demo.calculator.add(1, 2), 3);
  });

  it('exposes stats', () => {
    assert.equal(demo.stats.mean([2, 4]), 3);
  });

  it('exposes strings', () => {
    assert.equal(demo.strings.capitalize('x'), 'X');
  });
});

